module DeliveryTimeSolver (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] A_x, A_y,\n    input [15:0] B_x, B_y,\n    input [31:0] L_M,\n    input [15:0] C_x, C_y,\n    input [15:0] D_x, D_y,\n    input [31:0] L_N,\n    output reg [31:0] result,\n    output reg done,\n    output reg impossible\n);\n    \n    // Parameters\n    localparam [7:0] FRAC = 8;\n    localparam [15:0] SCALE = 256;\n    localparam [31:0] SCALE_SQ = 65536;\n    localparam [7:0] MAX_ITER = 8'd24;\n    \n    // States\n    localparam [2:0] \n        IDLE       = 3'd0,\n        INIT_BIN   = 3'd1,\n        FEAS_CHECK = 3'd2,\n        UPDATE_BIN = 3'd3,\n        FINISH     = 3'd4,\n        IMPOSSIBLE = 3'd5;\n    \n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [31:0] low, high, mid;\n    reg [31:0] t1, t2;\n    reg [15:0] Mx, My, Nx, Ny;\n    reg signed [16:0] dx, dy;\n    reg [31:0] dist_sq;\n    reg [31:0] threshold, T_sq;\n    reg [31:0] cycles;\n    reg feas_flag;\n    reg [7:0] s, u;\n    reg [7:0] s_counter;\n    reg [2:0] check_step;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            result <= 32'd0;\n            low <= 32'd0;\n            high <= 32'd0;\n            mid <= 32'd0;\n            t1 <= 32'd0;\n            t2 <= 32'd0;\n            Mx <= 16'd0;\n            My <= 16'd0;\n            Nx <= 16'd0;\n            Ny <= 16'd0;\n            dx <= 17'd0;\n            dy <= 17'd0;\n            dist_sq <= 32'd0;\n            threshold <= 32'd0;\n            T_sq <= 32'd0;\n            cycles <= 32'd0;\n            feas_flag <= 1'b0;\n            s <= 8'd0;\n            u <= 8'd0;\n            s_counter <= 8'd0;\n            check_step <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    if (start) begin\n                        low <= 32'd0;\n                        high <= (1 << 24) - 1; // Initial high bound\n                        cycles <= 32'd0;\n                        state <= INIT_BIN;\n                    end\n                end\n                \n                INIT_BIN: begin\n                    mid <= (low + high) >> 1;\n                    feas_flag <= 1'b0;\n                    s_counter <= 8'd0;\n                    check_step <= 3'd0;\n                    state <= FEAS_CHECK;\n                end\n                \n                FEAS_CHECK: begin\n                    case (check_step)\n                        3'd0: begin\n                            t1 <= (s_counter * L_M) >> FRAC;\n                            check_step <= check_step + 1;\n                        end\n                        \n                        3'd1: begin\n                            t2 <= t1 + mid;\n                            check_step <= check_step + 1;\n                        end\n                        \n                        3'd2: begin\n                            if (t2 > L_N) begin\n                                // Early termination for this s\n                                if (s_counter == 8'd255) begin\n                                    state <= UPDATE_BIN;\n                                end else begin\n                                    s_counter <= s_counter + 1;\n                                    check_step <= 3'd0;\n                                end\n                            end else begin\n                                u <= (t2 * SCALE) / L_N;\n                                check_step <= check_step + 1;\n                            end\n                        end\n                        \n                        3'd3: begin\n                            if (u > 8'd255) begin\n                                if (s_counter == 8'd255) begin\n                                    state <= UPDATE_BIN;\n                                end else begin\n                                    s_counter <= s_counter + 1;\n                                    check_step <= 3'd0;\n                                end\n                            end else begin\n                                Mx <= A_x + (((B_x - A_x) * s_counter) >> FRAC);\n                                My <= A_y + (((B_y - A_y) * s_counter) >> FRAC);\n                                check_step <= check_step + 1;\n                            end\n                        end\n                        \n                        3'd4: begin\n                            Nx <= C_x + (((D_x - C_x) * u) >> FRAC);\n                            Ny <= C_y + (((D_y - C_y) * u) >> FRAC);\n                            dx <= Mx - Nx;\n                            dy <= My - Ny;\n                            check_step <= check_step + 1;\n                        end\n                        \n                        3'd5: begin\n                            dist_sq <= (dx * dx) + (dy * dy);\n                            check_step <= check_step + 1;\n                        end\n                        \n                        3'd6: begin\n                            threshold <= dist_sq * SCALE_SQ;\n                            T_sq <= mid * mid;\n                            check_step <= check_step + 1;\n                        end\n                        \n                        3'd7: begin\n                            if (threshold <= T_sq) begin\n                                feas_flag <= 1'b1;\n                                state <= UPDATE_BIN;\n                            end else if (s_counter == 8'd255) begin\n                                state <= UPDATE_BIN;\n                            end else begin\n                                s_counter <= s_counter + 1;\n                                check_step <= 3'd0;\n                            end\n                        end\n                        \n                        default: check_step <= 3'd0;\n                    endcase\n                end\n                \n                UPDATE_BIN: begin\n                    if (feas_flag) begin\n                        high <= mid;\n                    end else begin\n                        low <= mid + 1;\n                    end\n                    \n                    if (high < low) begin\n                        state <= IMPOSSIBLE;\n                    end else if (((high - low) <= 32'd1) || (cycles >= MAX_ITER)) begin\n                        state <= FINISH;\n                    end else begin\n                        cycles <= cycles + 1;\n                        state <= INIT_BIN;\n                    end\n                end\n                \n                FINISH: begin\n                    result <= high << 8; // Convert to Q16.16\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                IMPOSSIBLE: begin\n                    impossible <= 1'b1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule